<?php declare(strict_types=1); require_once __DIR__.'/lib/auth.php'; if (current_user()) { header('Location: workspace.php'); exit; } $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim((string)($_POST['name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $pass=(string)($_POST['password']??''); $confirm=(string)($_POST['confirm_password']??''); if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL)) $error='Vui lòng nhập họ tên và email hợp lệ.'; elseif (strlen($pass)<8) $error='Mật khẩu phải có ít nhất 8 ký tự.'; elseif ($pass!==$confirm) $error='Mật khẩu nhập lại không khớp.'; else { try { $q=db()->prepare('SELECT id FROM users WHERE email=? LIMIT 1'); $q->execute([$email]); if ($q->fetch()) $error='Email này đã được đăng ký.'; else { $expires=(new DateTimeImmutable('+30 days'))->format('Y-m-d H:i:s'); $q=db()->prepare('INSERT INTO users(name,email,password_hash,status,role,expires_at) VALUES(?,?,?,?,?,?)'); $q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),'active','user',$expires]); header('Location: login.php?registered=1'); exit; } } catch(Throwable $e) { $error='Không thể tạo tài khoản. Kiểm tra cấu hình MySQL.'; } } } ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đăng ký - VideoDubing AI</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="auth-page"><section class="auth-card"><a class="auth-brand" href="index.php">▶ <strong>VideoDubing AI</strong></a><h1>Tạo tài khoản</h1><p class="hint">Đăng ký để sử dụng Download, Lồng tiếng và Phụ đề.</p><?php if($error): ?><div class="alert error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif; ?><form method="post"><div class="field"><label>Họ tên</label><input class="input" name="name" required value="<?=htmlspecialchars((string)($_POST['name']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required value="<?=htmlspecialchars((string)($_POST['email']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="field"><label>Mật khẩu</label><input class="input" type="password" name="password" minlength="8" required></div><div class="field"><label>Nhập lại mật khẩu</label><input class="input" type="password" name="confirm_password" minlength="8" required></div><button class="primary" style="width:100%">ĐĂNG KÝ</button></form><p class="auth-bottom">Đã có tài khoản? <a href="login.php">Đăng nhập</a></p></section></main></body></html>
